void printPairs(const std::vector<int>& v) {
    for (int i = 0; i < v.size() - 1; i++) {
        std::cout << v[i] << "-" << v[i + 1] << " ";
    }
}

std::vector<int> empty;
printPairs(empty);

def build_string(items):
